// ---- Detect default and mark default font size increase (for accessibility) ----
  function detectFontSizeIncrease() {
    // Get the root font size in pixels
    const rootFontSize = parseFloat(
      getComputedStyle(document.documentElement).fontSize
    );
    // Default is typically 16px
    const defaultSize = 16;
    const multiplier = rootFontSize / defaultSize;
    // Add or remove class based on multiplier
    if (multiplier >= 2) {
      document.body.classList.add('font-size-increased');
    } else {
      document.body.classList.remove('font-size-increased');
    }
  }
  // Run on load
  detectFontSizeIncrease();
  // Watch for changes (when user adjusts font size)
  const observer = new ResizeObserver(() => {
    detectFontSizeIncrease();
  });
  observer.observe(document.documentElement);
  // ---- Update foot year to current year ----
  document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('[data-footer-year]').forEach(el => {
      el.textContent = new Date().getFullYear();
    });
  });

function initAccordionCSS() {
  document.querySelectorAll('[data-accordion-css-init]').forEach((accordion) => {
    const closeSiblings = accordion.getAttribute('data-accordion-close-siblings') === 'true';
    accordion.addEventListener('click', (event) => {
      const toggle = event.target.closest('[data-accordion-toggle]');
      if (!toggle) return; // Exit if the clicked element is not a toggle
      const singleAccordion = toggle.closest('[data-accordion-status]');
      if (!singleAccordion) return; // Exit if no accordion container is found
      const isActive = singleAccordion.getAttribute('data-accordion-status') === 'active';
      singleAccordion.setAttribute('data-accordion-status', isActive ? 'not-active' : 'active');
      // When [data-accordion-close-siblings="true"]
      if (closeSiblings && !isActive) {
        accordion.querySelectorAll('[data-accordion-status="active"]').forEach((sibling) => {
          if (sibling !== singleAccordion) sibling.setAttribute('data-accordion-status', 'not-active');
        });
      }
    });
  });
}
// Initialize Accordion CSS
document.addEventListener('DOMContentLoaded', () => {
  initAccordionCSS();
});

// Initialize Multilevel Navigation
document.addEventListener("DOMContentLoaded", () => {
  initNavigation();
  initDetectScrollingDirection();
  showGehalteDropdown();
});
function initNavigation() {
  if (!initNavigation._hasResizeListener) {
    initNavigation._hasResizeListener = true;
    window.addEventListener("resize", debounce(initNavigation, 200));
  }
  const isMobile = window.innerWidth < 768;
  if (isMobile && initNavigation._lastMode !== "mobile") {
    initMobileMenu();
    initNavigation._lastMode = "mobile";
  } else if (!isMobile && initNavigation._lastMode !== "desktop") {
    initDesktopDropdowns();
    initNavigation._lastMode = "desktop";
  }
}
function debounce(fn, delay) {
  let timer;
  return () => {
    clearTimeout(timer);
    timer = setTimeout(fn, delay);
  };
}
function initMobileMenu() {
  const btn = document.querySelector("[data-menu-button]");
  const nav = document.querySelector("[data-menu-status]");
  if (!btn || !nav) return;
  btn.setAttribute("aria-expanded", "false");
  btn.setAttribute("aria-controls", "mobile-navigation");
  nav.setAttribute("id", "mobile-navigation");
  nav.setAttribute("role", "navigation");
  nav.setAttribute("aria-label", "Main navigation");
  if (!btn._mobileClick) {
    btn._mobileClick = true;
    btn.addEventListener("click", () => {
      const open = nav.dataset.menuStatus === "open";
      nav.dataset.menuStatus = open ? "closed" : "open";
      btn.setAttribute("aria-expanded", !open);
      // Close all dropdowns when closing the menu
      if (open) {
        Array.from(document.querySelectorAll("[data-dropdown-toggle]")).forEach(
          (toggle) => {
            toggle.dataset.dropdownToggle = "closed";
            toggle.setAttribute("aria-expanded", "false");
          }
        );
      }
    });
  }
  Array.from(document.querySelectorAll("[data-dropdown-toggle]")).forEach(
    (toggle, i) => {
      const dd = toggle.nextElementSibling;
      if (!dd || !dd.classList.contains("nav-dropdown")) return;
      if (toggle._mobileDropdownInit) return;
      toggle._mobileDropdownInit = true;
      toggle.setAttribute("aria-expanded", "false");
      toggle.setAttribute("aria-haspopup", "true");
      toggle.setAttribute("aria-controls", `dropdown-${i}`);
      dd.setAttribute("id", `dropdown-${i}`);
      dd.setAttribute("role", "menu");
      dd.querySelectorAll(".nav-dropdown__link").forEach((link) =>
        link.setAttribute("role", "menuitem")
      );
      toggle.addEventListener("click", () => {
        const open = toggle.dataset.dropdownToggle === "open";
        Array.from(document.querySelectorAll("[data-dropdown-toggle]")).forEach(
          (other) => {
            if (other !== toggle) {
              other.dataset.dropdownToggle = "closed";
              other.setAttribute("aria-expanded", "false");
              if (other === document.activeElement) other.blur();
            }
          }
        );
        toggle.dataset.dropdownToggle = open ? "closed" : "open";
        toggle.setAttribute("aria-expanded", !open);
        if (open && toggle === document.activeElement) toggle.blur();
      });
    }
  );
}
function initDesktopDropdowns() {
  const toggles = Array.from(
    document.querySelectorAll("[data-dropdown-toggle]")
  );
  const links = Array.from(
    document.querySelectorAll(".nav-link:not([data-dropdown-toggle])")
  );
  toggles.forEach((toggle, i) => {
    const dd = toggle.nextElementSibling;
    if (!dd || !dd.classList.contains("nav-dropdown") || toggle._desktopInit)
      return;
    toggle._desktopInit = true;
    toggle.setAttribute("aria-expanded", "false");
    toggle.setAttribute("aria-haspopup", "true");
    toggle.setAttribute("aria-controls", `desktop-dropdown-${i}`);
    dd.setAttribute("id", `desktop-dropdown-${i}`);
    dd.setAttribute("role", "menu");
    dd.setAttribute("aria-hidden", "true");
    dd.querySelectorAll(".nav-dropdown__link").forEach((link) =>
      link.setAttribute("role", "menuitem")
    );
    toggle.addEventListener("click", (e) => {
      e.preventDefault();
      toggles.forEach((other) => {
        if (other !== toggle) {
          other.dataset.dropdownToggle = "closed";
          other.setAttribute("aria-expanded", "false");
          const otherDropdown = other.nextElementSibling;
          if (otherDropdown) otherDropdown.setAttribute("aria-hidden", "true");
        }
      });
      const open = toggle.dataset.dropdownToggle !== "open";
      toggle.dataset.dropdownToggle = "open";
      toggle.setAttribute("aria-expanded", "true");
      dd.setAttribute("aria-hidden", "false");
      if (open) {
        const first = dd.querySelector(".nav-dropdown__link");
        if (first) first.focus();
      }
    });
    toggle.addEventListener("mouseenter", () => {
      const anyOpen = toggles.some((x) => x.dataset.dropdownToggle === "open");
      toggles.forEach((other) => {
        if (other !== toggle) {
          other.dataset.dropdownToggle = "closed";
          other.setAttribute("aria-expanded", "false");
          const otherDropdown = other.nextElementSibling;
          if (otherDropdown) otherDropdown.setAttribute("aria-hidden", "true");
        }
      });
      if (anyOpen) {
        setTimeout(() => {
          toggle.dataset.dropdownToggle = "open";
          toggle.setAttribute("aria-expanded", "true");
          dd.setAttribute("aria-hidden", "false");
        }, 20);
      } else {
        toggle.dataset.dropdownToggle = "open";
        toggle.setAttribute("aria-expanded", "true");
        dd.setAttribute("aria-hidden", "false");
      }
    });
    dd.addEventListener("mouseleave", () => {
      toggle.dataset.dropdownToggle = "closed";
      toggle.setAttribute("aria-expanded", "false");
      dd.setAttribute("aria-hidden", "true");
    });
    toggle.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        toggle.click();
      } else if (e.key === "Escape") {
        toggle.dataset.dropdownToggle = "closed";
        toggle.setAttribute("aria-expanded", "false");
        dd.setAttribute("aria-hidden", "true");
        toggle.focus();
      }
    });
    dd.addEventListener("keydown", (e) => {
      const items = Array.from(dd.querySelectorAll(".nav-dropdown__link"));
      const idx = items.indexOf(document.activeElement);
      if (e.key === "ArrowDown") {
        e.preventDefault();
        items[(idx + 1) % items.length].focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        items[(idx - 1 + items.length) % items.length].focus();
      } else if (e.key === "Escape") {
        e.preventDefault();
        toggle.dataset.dropdownToggle = "closed";
        toggle.setAttribute("aria-expanded", "false");
        dd.setAttribute("aria-hidden", "true");
        toggle.focus();
      } else if (e.key === "Tab" && !dd.contains(e.relatedTarget)) {
        toggle.dataset.dropdownToggle = "closed";
        toggle.setAttribute("aria-expanded", "false");
        dd.setAttribute("aria-hidden", "true");
      }
    });
  });
  links.forEach((link) => {
    link.addEventListener("mouseenter", () => {
      toggles.forEach((toggle) => {
        toggle.dataset.dropdownToggle = "closed";
        toggle.setAttribute("aria-expanded", "false");
        const dd = toggle.nextElementSibling;
        if (dd) dd.setAttribute("aria-hidden", "true");
      });
    });
  });
  document.addEventListener("click", (e) => {
    const inside = toggles.some((toggle) => {
      const dd = toggle.nextElementSibling;
      return toggle.contains(e.target) || (dd && dd.contains(e.target));
    });
    if (!inside) {
      toggles.forEach((toggle) => {
        toggle.dataset.dropdownToggle = "closed";
        toggle.setAttribute("aria-expanded", "false");
        const dd = toggle.nextElementSibling;
        if (dd) dd.setAttribute("aria-hidden", "true");
      });
    }
  });
}
function initDetectScrollingDirection() {
  let lastScrollTop = 0;
  const threshold = 10; // Minimal scroll distance to switch to up/down
  const thresholdTop = 50; // Minimal scroll distance from top of window to start
  window.addEventListener("scroll", () => {
    const nowScrollTop = window.scrollY;
    if (Math.abs(lastScrollTop - nowScrollTop) >= threshold) {
      // Update Scroll Direction
      const direction = nowScrollTop > lastScrollTop ? "down" : "up";
      document
        .querySelectorAll("[data-scrolling-direction]")
        .forEach((el) =>
          el.setAttribute("data-scrolling-direction", direction)
        );
      // Update Scroll Started
      const started = nowScrollTop > thresholdTop;
      document
        .querySelectorAll("[data-scrolling-started]")
        .forEach((el) =>
          el.setAttribute("data-scrolling-started", started ? "true" : "false")
        );
      lastScrollTop = nowScrollTop;
    }
  });
}
function showGehalteDropdown() {
  // Object om alle dropdown HTML op te slaan
  const dropdownStorage = {};
  // Selecteer alle gehalte dropdowns en sla ze op
  const gehalteDropdowns = document.querySelectorAll("[data-gehalte]");
  gehalteDropdowns.forEach((dropdown) => {
    const gehalteType = dropdown.getAttribute("data-gehalte");
    // Sla de hele dropdown HTML op
    dropdownStorage[gehalteType] = dropdown.cloneNode(true);
    // Verwijder alles behalve goud uit de DOM
    if (gehalteType !== "goud") {
      dropdown.remove();
    }
  });
  // Zorg dat goud dropdown zichtbaar is en correct ingesteld
  const goudDropdown = document.querySelector('[data-gehalte="goud"]');
  if (goudDropdown) {
    goudDropdown.style.display = "block";
    const select = goudDropdown.querySelector("select");
    if (select) {
      select.setAttribute("required", "required");
    }
  }
  // Event listener voor wijzigingen
  const gehalteSelect = document.querySelector("[data-gehalte-select]");
  if (gehalteSelect) {
    gehalteSelect.addEventListener("change", (e) => {
      const selectedValue = e.target.value.toLowerCase();
      // Verwijder alle bestaande gehalte dropdowns
      document.querySelectorAll("[data-gehalte]").forEach((dropdown) => {
        dropdown.remove();
      });
      // Haal de juiste dropdown op uit de storage
      const storedDropdown = dropdownStorage[selectedValue];
      if (storedDropdown) {
        // Clone de opgeslagen dropdown
        const newDropdown = storedDropdown.cloneNode(true);
        newDropdown.style.display = "block";
        // Zorg dat de select correct is ingesteld
        const select = newDropdown.querySelector("select");
        if (select) {
          select.setAttribute("required", "required");
          select.selectedIndex = 0; // Reset naar "Selecteer een..."
        }
        // Voeg de dropdown toe aan de juiste plek in de DOM
        // Zoek de parent container (.col) waar de dropdown in moet
        const parentCol = gehalteSelect
          .closest(".col")
          .parentElement.querySelector(".col:last-child");
        if (parentCol) {
          parentCol.appendChild(newDropdown);
        }
      }
    });
  }
}

