function initDetectScrollingDirection() {
  let lastScrollTop = 0;
  const threshold = 10; // Minimal scroll distance to switch to up/down
  const thresholdTop = 50; // Minimal scroll distance from top of window to start
  window.addEventListener("scroll", () => {
    const nowScrollTop = window.scrollY;
    if (Math.abs(lastScrollTop - nowScrollTop) >= threshold) {
      // Update Scroll Direction
      const direction = nowScrollTop > lastScrollTop ? "down" : "up";
      document
        .querySelectorAll("[data-scrolling-direction]")
        .forEach((el) =>
          el.setAttribute("data-scrolling-direction", direction)
        );
      // Update Scroll Started
      const started = nowScrollTop > thresholdTop;
      document
        .querySelectorAll("[data-scrolling-started]")
        .forEach((el) =>
          el.setAttribute("data-scrolling-started", started ? "true" : "false")
        );
      lastScrollTop = nowScrollTop;
    }
  });
}
function showGehalteDropdown() {
  // Object om alle dropdown HTML op te slaan
  const dropdownStorage = {};
  // Selecteer alle gehalte dropdowns en sla ze op
  const gehalteDropdowns = document.querySelectorAll("[data-gehalte]");
  gehalteDropdowns.forEach((dropdown) => {
    const gehalteType = dropdown.getAttribute("data-gehalte");
    // Sla de hele dropdown HTML op
    dropdownStorage[gehalteType] = dropdown.cloneNode(true);
    // Verwijder alles behalve goud uit de DOM
    if (gehalteType !== "goud") {
      dropdown.remove();
    }
  });
  // Zorg dat goud dropdown zichtbaar is en correct ingesteld
  const goudDropdown = document.querySelector('[data-gehalte="goud"]');
  if (goudDropdown) {
    goudDropdown.style.display = "block";
    const select = goudDropdown.querySelector("select");
    if (select) {
      select.setAttribute("required", "required");
    }
  }
  // Event listener voor wijzigingen
  const gehalteSelect = document.querySelector("[data-gehalte-select]");
  if (gehalteSelect) {
    gehalteSelect.addEventListener("change", (e) => {
      const selectedValue = e.target.value.toLowerCase();
